PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS patients(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS departments(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS doctors(id TEXT PRIMARY KEY,department_id TEXT REFERENCES departments(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,patient_id TEXT REFERENCES patients(id),doctor_id TEXT REFERENCES doctors(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS staff(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,patient_id TEXT REFERENCES patients(id),doctor_id TEXT REFERENCES doctors(id),appointment_date TEXT,appointment_time TEXT,status TEXT NOT NULL,payload TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS appointments_no_double_book ON appointments(doctor_id,appointment_date,appointment_time) WHERE status NOT IN ('Cancelled','No Show');
CREATE INDEX IF NOT EXISTS appointments_by_date ON appointments(appointment_date,status);
CREATE TABLE IF NOT EXISTS medical_records(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),doctor_id TEXT REFERENCES doctors(id),payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS records_by_patient ON medical_records(patient_id);
CREATE TABLE IF NOT EXISTS vital_signs(id TEXT PRIMARY KEY,medical_record_id TEXT NOT NULL REFERENCES medical_records(id) ON DELETE CASCADE,blood_pressure TEXT,heart_rate REAL,temperature REAL,respiratory_rate REAL,oxygen_saturation REAL,weight REAL,height REAL);
CREATE TABLE IF NOT EXISTS prescriptions(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),doctor_id TEXT REFERENCES doctors(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS prescription_items(id TEXT PRIMARY KEY,prescription_id TEXT NOT NULL REFERENCES prescriptions(id) ON DELETE CASCADE,name TEXT NOT NULL,dosage TEXT,frequency TEXT,duration TEXT);
CREATE TABLE IF NOT EXISTS lab_tests(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),doctor_id TEXT REFERENCES doctors(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lab_results(id TEXT PRIMARY KEY,lab_test_id TEXT NOT NULL REFERENCES lab_tests(id) ON DELETE CASCADE,result TEXT NOT NULL,normal_range TEXT,remarks TEXT,completed_at TEXT);
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS beds(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES rooms(id),label TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Available',UNIQUE(room_id,label));
CREATE TABLE IF NOT EXISTS admissions(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),doctor_id TEXT REFERENCES doctors(id),room TEXT,bed TEXT,status TEXT NOT NULL,payload TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS active_bed_assignment ON admissions(room,bed) WHERE status!='Discharged';
CREATE TABLE IF NOT EXISTS invoices(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoice_items(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,description TEXT NOT NULL,quantity REAL NOT NULL DEFAULT 1,unit_price REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoices(id),amount REAL NOT NULL CHECK(amount>0),method TEXT,paid_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS medicines(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_transactions(id TEXT PRIMARY KEY,medicine_id TEXT NOT NULL REFERENCES medicines(id),quantity_change REAL NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,patient_id TEXT REFERENCES patients(id),payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS notifications_by_patient ON notifications(patient_id);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hospital_settings(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
